const servicios = /* #__PURE__ */ JSON.parse("[{\"id\":101,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-17T17:36:11.089Z\",\"user_updated\":null,\"date_updated\":\"2026-01-17T17:36:11.089Z\",\"Titulo\":\"Infraestructura de Redes | Cableado, Fibra Óptica, Radioenlaces\",\"Descripcion\":\"Diseño e implementación de infraestructura de redes de datos en Mendoza, San Juan, San Luis y Cuyo. Soluciones completas: cableado estructurado Cat 6/6A/7, fibra óptica, radioenlaces, LAN/WAN, data centers. +94 proyectos exitosos en minería, bodegas, constructoras, gobierno y salud. Certificación TIA/EIA. Garantía extendida.\",\"Area\":\"Redes\",\"Cliente\":null,\"Unidad_de_negocio\":\"Infraestructura\",\"Imagen\":\"a404fe13-25dc-409d-9789-02cbf9fb93c1\",\"Presupuesto\":null,\"Servicios_Detalle\":null,\"Caracteristicas\":null,\"original_id\":null,\"Subtitulo\":\"Conectividad de Alta Performance para Organizaciones Exigentes\",\"Tagline\":\"La columna vertebral de su transformación digital\",\"Stats\":[{\"valor\":\"469+\",\"label\":\"Proyectos ejecutados\"},{\"valor\":\"25+\",\"label\":\"Años de experiencia\"},{\"valor\":\"100%\",\"label\":\"Certificación garantizada\"}],\"Productos\":[{\"nombre\":\"Fibra Óptica de Alta Capacidad\",\"headline\":\"Velocidad sin límites para su organización\",\"descripcion\":\"Olvídese de los cuellos de botella. Con nuestra instalación certificada de fibra óptica, sus datos viajan a la velocidad de la luz. Ideal para interconectar edificios, data centers o llevar conectividad donde el cobre no alcanza.\",\"servicio_asociado\":\"🔧 Instalamos enlaces de fibra óptica monomodo y multimodo con fusiones certificadas, mediciones OTDR y garantía de 25 años.\",\"imagen\":\"/images/services/productos/infraestructura/1.1.png\",\"caracteristicas\":[\"Velocidades de hasta 100 Gbps\",\"Inmune a interferencias electromagnéticas\",\"Distancias de hasta 80 km sin repetidores\"]},{\"nombre\":\"Centro de Distribución de Red\",\"headline\":\"El corazón ordenado de toda su infraestructura\",\"descripcion\":\"Un patch panel bien instalado es la diferencia entre encontrar un problema en minutos o en horas. Centralizamos todas sus conexiones en un punto de gestión profesional que facilita el mantenimiento, las expansiones y el troubleshooting.\",\"servicio_asociado\":\"🔧 Instalamos racks completos con patch panels certificados, organizadores verticales, etiquetado profesional y documentación de cada puerto.\",\"imagen\":\"/images/services/productos/infraestructura/1.2.png\",\"caracteristicas\":[\"Identifique cualquier punto en segundos\",\"Agregue conexiones sin rediseñar\",\"Blindaje contra interferencias Cat6A\"]},{\"nombre\":\"Cableado Estructurado Certificado\",\"headline\":\"Cada punto de red, garantizado y documentado\",\"descripcion\":\"No instalamos cables, construimos infraestructura. Cada punto que instalamos viene con su certificación Fluke individual. Usted recibe un informe con los valores de medición de cada conexión — su garantía ante cualquier auditoría o reclamo.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos redes de cableado estructurado Cat5e, Cat6 y Cat6A con certificación punto por punto y garantía del fabricante de 25 años.\",\"imagen\":\"/images/services/productos/infraestructura/1.3.png\",\"caracteristicas\":[\"Certificación individual Fluke\",\"Garantía de 25 años\",\"Cumplimiento TIA/EIA-568-C\"]},{\"nombre\":\"Switching de Alto Rendimiento\",\"headline\":\"Conectividad inteligente que nunca se detiene\",\"descripcion\":\"Su red necesita un cerebro que tome decisiones en microsegundos. Implementamos equipos de switching empresarial con redundancia, gestión remota y la capacidad de crecer con su organización. Monitoreo proactivo incluido.\",\"servicio_asociado\":\"🔧 Configuramos y mantenemos su infraestructura de switching con VLANs, QoS, redundancia y monitoreo 24/7. Soporte remoto y presencial.\",\"imagen\":\"/images/services/productos/infraestructura/1.4.png\",\"caracteristicas\":[\"Cero downtime con redundancia\",\"Gestión remota segura\",\"Arquitectura modular escalable\"]},{\"nombre\":\"Data Center Llave en Mano\",\"headline\":\"Su centro de cómputos, profesionalmente implementado\",\"descripcion\":\"Desde el piso técnico hasta el último cable, diseñamos e instalamos cuartos de comunicaciones que cumplen estándares internacionales. Climatización, energía redundante, control de acceso y monitoreo ambiental integrados.\",\"servicio_asociado\":\"🔧 Construimos data centers y cuartos de comunicaciones completos: obra civil, climatización, energía, racks, cableado y seguridad.\",\"imagen\":\"/images/services/productos/infraestructura/1.5.png\",\"caracteristicas\":[\"Diseño térmico optimizado\",\"Acceso y mantenimiento simplificado\",\"Cumplimiento TIA-942\"]},{\"nombre\":\"Radioenlaces Punto a Punto\",\"headline\":\"Conecte ubicaciones remotas sin tender un solo cable\",\"descripcion\":\"Cuando el cable no es opción, el aire es el camino. Diseñamos e instalamos radioenlaces de alta capacidad para unir edificios, sucursales o sitios remotos. Enlaces licenciados y no licenciados con SLA de disponibilidad.\",\"servicio_asociado\":\"🔧 Implementamos radioenlaces profesionales con estudio de factibilidad, trámites regulatorios (si aplica), instalación y mantenimiento con SLA.\",\"imagen\":\"/images/services/productos/infraestructura/1.6.png\",\"caracteristicas\":[\"Distancias de hasta 50 km\",\"Velocidades de hasta 1 Gbps\",\"99.99% de disponibilidad\"]},{\"nombre\":\"Certificación Profesional de Red\",\"headline\":\"Cada punto que instalamos, lo certificamos\",\"descripcion\":\"No confíe en 'funciona bien'. Exija la prueba. Con nuestro equipamiento Fluke de última generación, cada punto de red recibe su certificación individual con valores de medición reales. Documentación válida para auditorías y garantías de fabricante.\",\"servicio_asociado\":\"🔧 Certificamos instalaciones nuevas y existentes con equipos Fluke DSX. Emitimos reportes PDF individuales válidos para auditorías y activación de garantías.\",\"imagen\":\"/images/services/productos/infraestructura/1.7.png\",\"caracteristicas\":[\"Reporte PDF por cada punto\",\"Válido para garantías 25 años\",\"Detecta fallas ocultas\"]},{\"nombre\":\"Gestión Profesional de Fibra Óptica\",\"headline\":\"Orden y escalabilidad para su backbone de fibra\",\"descripcion\":\"La fibra óptica es delicada y valiosa. La organizamos con precisión quirúrgica: fusiones protegidas, identificación clara por código de colores, y acceso pensado para mantenimiento sin riesgo. Cada fusión documentada y medida.\",\"servicio_asociado\":\"🔧 Instalamos ODFs y realizamos fusiones certificadas con empalmadora de precisión. Medición OTDR de cada hilo y documentación completa.\",\"imagen\":\"/images/services/productos/infraestructura/1.8.png\",\"caracteristicas\":[\"Fusiones con pérdida < 0.1 dB\",\"Expansión sin interrumpir servicio\",\"Identificación por código de colores\"]}],\"PorQueElegirnos\":[\"Certificación Fluke de cada punto instalado\",\"Garantía extendida de 25 años en cableado\",\"Cumplimiento normas TIA/EIA-568 y ISO/IEC 11801\"],\"ServiciosLista\":[\"Cableado Estructurado Cat6/Cat6A certificado\",\"Redes de Fibra Óptica (monomodo y multimodo)\",\"Radioenlaces punto a punto y multipunto\",\"Data Centers y cuartos de comunicaciones\",\"Redes corporativas LAN/WAN\"],\"AntecedentesIds\":null,\"LocalFallbackImage\":\"/img/sync-offline/a404fe13-25dc-409d-9789-02cbf9fb93c1.png\"},{\"id\":102,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-17T17:36:11.089Z\",\"user_updated\":null,\"date_updated\":\"2026-01-17T17:36:11.089Z\",\"Titulo\":\"Sistemas de Seguridad Electrónica | CCTV, Control Acceso, Sistemas de Detección de Incendios (SDI)\",\"Descripcion\":\"Protección inteligente para lo que más importa. Soluciones integrales de seguridad en Mendoza, Cuyo y Patagonia. Videovigilancia CCTV IP, Sistemas de Detección de Incendios (SDI), control de acceso biométrico/RFID, alarmas, BMS. +67 proyectos en aeropuertos, minería, bodegas, hospitales y gobierno. Monitoreo 24/7, respuesta rápida a incidentes, cumplimiento normativo ISO 27001.\",\"Area\":\"Seguridad\",\"Cliente\":null,\"Unidad_de_negocio\":\"Seguridad\",\"Imagen\":\"992632c1-5d88-48ea-9bc5-53c59109694e\",\"Presupuesto\":null,\"Servicios_Detalle\":null,\"Caracteristicas\":null,\"original_id\":null,\"Subtitulo\":\"Detección de Incendios, CCTV y Control de Acceso\",\"Tagline\":\"Protección inteligente para lo que más importa\",\"Stats\":[{\"valor\":\"50+\",\"label\":\"Sistemas SDI instalados\"},{\"valor\":\"100+\",\"label\":\"Sistemas CCTV desplegados\"},{\"valor\":\"24/7\",\"label\":\"Monitoreo disponible\"}],\"Productos\":[{\"nombre\":\"Videovigilancia IP Profesional\",\"headline\":\"Ojos que nunca duermen, en cada rincón\",\"descripcion\":\"Vea todo, siempre, desde cualquier lugar. Nuestras cámaras IP de alta definición capturan cada detalle en tiempo real. Visión nocturna, análisis inteligente y acceso remoto desde su celular. Disuasión y evidencia en un solo sistema.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos sistemas CCTV IP completos: cámaras, grabadores NVR, almacenamiento y monitoreo remoto. Mantenimiento preventivo incluido.\",\"imagen\":\"/images/services/productos/seguridad/2.1.png\",\"caracteristicas\":[\"Acceso desde cualquier dispositivo\",\"Grabación continua 24/7\",\"Análisis inteligente con IA\"]},{\"nombre\":\"Cámaras de Exterior Alta Definición\",\"headline\":\"Vigilancia perimetral que no perdona detalles\",\"descripcion\":\"Para exteriores exigentes: sol, lluvia, polvo. Nuestras cámaras bullet IP están diseñadas para condiciones extremas. Visión nocturna de largo alcance, lente ajustable y carcasa anti-vandálica. Protección real donde más se necesita.\",\"servicio_asociado\":\"🔧 Instalamos sistemas de videovigilancia exterior con cámaras antivandalismo IP67, iluminación IR y cableado protegido. Ideal para perímetros y estacionamientos.\",\"imagen\":\"/images/services/productos/seguridad/2.2.png\",\"caracteristicas\":[\"Visión nocturna hasta 80 metros\",\"Resistencia IP67\",\"Carcasa antivandalismo IK10\"]},{\"nombre\":\"Sistema de Detección de Incendios\",\"headline\":\"Segundos que salvan vidas y activos\",\"descripcion\":\"El fuego avanza rápido. Su sistema de detección debe ser más rápido. Instalamos detectores de humo fotoeléctricos que identifican el inicio de un incendio antes de que las llamas aparezcan. Cumplimiento NFPA 72 y certificación de Bomberos.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos sistemas de detección de incendios (SDI) completos: detectores, panel central, sirenas y señalización. Habilitación ante Bomberos incluida.\",\"imagen\":\"/images/services/productos/seguridad/2.3.png\",\"caracteristicas\":[\"Detección temprana\",\"Certificación NFPA 72\",\"Habilitación Bomberos incluida\"]},{\"nombre\":\"Panel Central de Alarma SDI\",\"headline\":\"El cerebro que coordina la protección contra incendios\",\"descripcion\":\"Todos los detectores reportan aquí. El panel central monitorea cada zona, activa sirenas, libera puertas de emergencia y notifica a la central de monitoreo. Interfaz clara para que cualquier persona pueda entender el estado del sistema.\",\"servicio_asociado\":\"🔧 Instalamos y programamos paneles de alarma de incendios convencionales y direccionables. Integración con sistemas de evacuación, rociadores y monitoreo 24/7.\",\"imagen\":\"/images/services/productos/seguridad/2.4.png\",\"caracteristicas\":[\"Monitoreo por zonas\",\"Integración total\",\"Interfaz intuitiva\"]},{\"nombre\":\"Estaciones Manuales de Alarma\",\"headline\":\"Cualquier persona puede dar la alerta\",\"descripcion\":\"Cuando alguien detecta fuego antes que el sistema, necesita una forma de alertar a todos. Las estaciones manuales ubicadas estratégicamente permiten activar la alarma general con un simple gesto. Cumplimiento normativo garantizado.\",\"servicio_asociado\":\"🔧 Instalamos estaciones manuales de alarma en ubicaciones normativas: salidas de emergencia, pasillos y áreas de alta ocupación. Señalización fotoluminiscente incluida.\",\"imagen\":\"/images/services/productos/seguridad/2.5.png\",\"caracteristicas\":[\"Activación instantánea\",\"Ubicación normativa\",\"Alta visibilidad\"]},{\"nombre\":\"Control de Acceso Biométrico\",\"headline\":\"Acceso solo para quien usted autorice\",\"descripcion\":\"La tarjeta se puede prestar, el PIN se puede compartir. La huella digital, no. Nuestros sistemas biométricos garantizan que solo las personas autorizadas ingresen a áreas restringidas. Registro completo de quién entró, cuándo y dónde.\",\"servicio_asociado\":\"🔧 Instalamos sistemas de control de acceso con lectores biométricos, tarjetas RFID, software de gestión y reportes. Integración con RRHH y nómina disponible.\",\"imagen\":\"/images/services/productos/seguridad/2.6.png\",\"caracteristicas\":[\"Imposible de falsificar\",\"Registro de accesos\",\"Integración con RRHH\"]},{\"nombre\":\"Grabación y Almacenamiento de Video\",\"headline\":\"Cada segundo grabado, listo para cuando lo necesite\",\"descripcion\":\"Las cámaras capturan, el NVR preserva. Almacenamiento de semanas o meses de video en alta definición, con búsqueda inteligente por fecha, hora o evento. Cuando necesite revisar un incidente, estará ahí.\",\"servicio_asociado\":\"🔧 Instalamos grabadores NVR con capacidad de 8 a 128 cámaras, almacenamiento redundante, acceso remoto y backup en nube opcional.\",\"imagen\":\"/images/services/productos/seguridad/2.7.png\",\"caracteristicas\":[\"Semanas de grabación\",\"Búsqueda inteligente\",\"Acceso remoto seguro\"]},{\"nombre\":\"Detección de Intrusos PIR\",\"headline\":\"Alerta temprana ante presencias no autorizadas\",\"descripcion\":\"Los sensores de movimiento PIR detectan la presencia humana por su calor corporal. Instalados en puntos estratégicos, activan alarmas ante intrusiones y pueden integrarse con cámaras para grabación por evento.\",\"servicio_asociado\":\"🔧 Instalamos sistemas de alarma perimetral con sensores PIR, contactos magnéticos, sirenas y monitoreo central 24/7.\",\"imagen\":\"/images/services/productos/seguridad/2.8.png\",\"caracteristicas\":[\"Detección por calor corporal\",\"Integración con CCTV\",\"Alertas en tiempo real\"]}],\"PorQueElegirnos\":[\"Certificación en sistemas Notifier, Hochiki, Bosch\",\"Personal propio capacitado en normas NFPA\",\"Servicio de mantenimiento preventivo programado\"],\"ServiciosLista\":[\"Sistemas de detección de incendio convencionales y analógicos\",\"Centrales de incendio certificadas IRAM/UL/FM\",\"CCTV IP con analítica de video\",\"Control de acceso biométrico y por credenciales\"],\"AntecedentesIds\":null,\"LocalFallbackImage\":\"/img/sync-offline/992632c1-5d88-48ea-9bc5-53c59109694e.png\"},{\"id\":103,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-17T17:36:11.089Z\",\"user_updated\":null,\"date_updated\":\"2026-01-17T17:36:11.089Z\",\"Titulo\":\"Telecomunicaciones. | Datos, Voz, Video\",\"Descripcion\":\"Diseño e implementación de planes de convergencia para redes de datos, voz y video, optimizando costos, infraestructura y energía, con más de 88 proyectos exitosos en minería, bodegas, constructoras, gobierno y salud.\",\"Area\":\"Telecomunicaciones\",\"Cliente\":null,\"Unidad_de_negocio\":\"Telecomunicaciones\",\"Imagen\":\"caffbcaa-2457-4fc9-9960-2e0601f27736\",\"Presupuesto\":null,\"Servicios_Detalle\":null,\"Caracteristicas\":null,\"original_id\":null,\"Subtitulo\":\"Comunicaciones Unificadas para la Empresa Moderna\",\"Tagline\":\"Comunicaciones que impulsan la productividad\",\"Stats\":[{\"valor\":\"200+\",\"label\":\"Sistemas de telefonía\"},{\"valor\":\"15+\",\"label\":\"Operadores integrados\"},{\"valor\":\"99.9%\",\"label\":\"Uptime garantizado\"}],\"Productos\":[{\"nombre\":\"Central Telefónica IP\",\"headline\":\"Comunicación empresarial sin límites\",\"descripcion\":\"Deje atrás las centrales analógicas. La telefonía IP reduce costos, mejora la calidad de audio y permite funcionalidades imposibles antes: conferencias, grabación, IVR, integración con CRM. Todo desde cualquier dispositivo.\",\"servicio_asociado\":\"🔧 Instalamos centrales telefónicas IP basadas en Asterisk, 3CX o Grandstream. Migración gradual, capacitación y soporte incluidos.\",\"imagen\":\"/images/services/productos/telecomunicaciones/3.1.png\",\"caracteristicas\":[\"VoIP de alta calidad\",\"Integración con móviles\",\"Grabación de llamadas\"]},{\"nombre\":\"Telefonía Cloud\",\"headline\":\"Sin inversión en hardware, máxima flexibilidad\",\"descripcion\":\"¿Por qué comprar equipos si puede pagar por uso? La telefonía cloud le da líneas, internos y funcionalidades avanzadas sin instalar nada en su oficina. Ideal para empresas distribuidas o en crecimiento.\",\"servicio_asociado\":\"🔧 Configuramos y migramos su telefonía a servicios cloud con numeración local, DID y SLA de disponibilidad garantizado.\",\"imagen\":\"/images/services/productos/telecomunicaciones/3.2.png\",\"caracteristicas\":[\"Cero hardware\",\"Escalabilidad infinita\",\"Pago por uso\"]},{\"nombre\":\"Sistema de Voceo y PA\",\"headline\":\"Comunicación masiva clara y profesional\",\"descripcion\":\"Aeropuertos, hospitales, fábricas: cuando necesita que todos escuchen el mismo mensaje al mismo tiempo, necesita un sistema de voceo profesional. Audio cristalino, zonas independientes, prioridad para emergencias.\",\"servicio_asociado\":\"🔧 Instalamos sistemas de voceo con amplificadores, parlantes de techo/pared/bocina y micrófonos. Integración con sistemas de emergencia disponible.\",\"imagen\":\"/images/services/productos/telecomunicaciones/3.3.png\",\"caracteristicas\":[\"Zonas independientes\",\"Integración con emergencias\",\"Audio de alta fidelidad\"]},{\"nombre\":\"Integración Microsoft Teams\",\"headline\":\"Telefonía nativa en su plataforma de colaboración\",\"descripcion\":\"Sus equipos ya usan Teams. ¿Por qué salir para hacer llamadas? Integramos telefonía pública directamente en Teams: reciba y realice llamadas, vea presencia de colegas, todo en una sola interfaz.\",\"servicio_asociado\":\"🔧 Configuramos Direct Routing o Operator Connect para Teams. Integración con su central existente o migración completa.\",\"imagen\":\"/images/services/productos/telecomunicaciones/3.4.png\",\"caracteristicas\":[\"Llamadas desde Teams\",\"Presencia unificada\",\"Colaboración en tiempo real\"]},{\"nombre\":\"Radiotroncalizado Digital\",\"headline\":\"Comunicación crítica para operaciones exigentes\",\"descripcion\":\"Cuando WiFi y celular no alcanzan, la radio profesional sigue funcionando. Sistemas DMR y TETRA para industria, emergencias, seguridad y logística. Cobertura garantizada donde más se necesita.\",\"servicio_asociado\":\"🔧 Implementamos sistemas de radio DMR y TETRA con repetidores, consolas de despacho y terminales móviles/portátiles.\",\"imagen\":\"/images/services/productos/telecomunicaciones/3.5.png\",\"caracteristicas\":[\"Cobertura extendida\",\"Encriptación de voz\",\"GPS integrado\"]},{\"nombre\":\"Videocolaboración Profesional\",\"headline\":\"Reuniones que parecen presenciales\",\"descripcion\":\"La sala de reuniones del futuro: pantallas de alta definición, audio que elimina el ruido de fondo, cámaras que siguen al orador. Colaboración efectiva sin importar dónde estén los participantes.\",\"servicio_asociado\":\"🔧 Diseñamos y equipamos salas de videoconferencia con pantallas, cámaras PTZ, audio Poly/Shure y codec de video. Integración con Teams/Zoom.\",\"imagen\":\"/images/services/productos/telecomunicaciones/3.6.png\",\"caracteristicas\":[\"4K Ultra HD\",\"Audio inmersivo\",\"Control táctil\"]}],\"PorQueElegirnos\":[\"Partner certificado de fabricantes líderes\",\"Migración gradual sin interrumpir operaciones\",\"Soporte técnico especializado 24/7\"],\"ServiciosLista\":[\"Centrales telefónicas IP y híbridas\",\"Telefonía cloud y VoIP empresarial\",\"Sistemas de voceo y PA\",\"Integración con Microsoft Teams y Zoom\"],\"AntecedentesIds\":3463,\"LocalFallbackImage\":\"/img/sync-offline/caffbcaa-2457-4fc9-9960-2e0601f27736.png\"},{\"id\":104,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-17T17:36:11.089Z\",\"user_updated\":null,\"date_updated\":\"2026-01-17T17:36:11.089Z\",\"Titulo\":\"Desarrollo de Software a Medida | Web, Mobile, ERP\",\"Descripcion\":\"Soluciones Digitales a Medida para Transformar su Negocio. Tecnología que trabaja para su negocio.\",\"Area\":\"Desarrollo\",\"Cliente\":null,\"Unidad_de_negocio\":\"Software\",\"Imagen\":\"be4911d3-7a71-457e-a081-97d0472c4aa9\",\"Presupuesto\":null,\"Servicios_Detalle\":null,\"Caracteristicas\":null,\"original_id\":null,\"Subtitulo\":\"Software a Medida que Impulsa su Negocio\",\"Tagline\":\"Soluciones digitales A MEDIDA de su proceso.\",\"Stats\":[{\"valor\":\"50+\",\"label\":\"Proyectos entregados\"},{\"valor\":\"10+\",\"label\":\"Años en desarrollo\"},{\"valor\":\"100%\",\"label\":\"Código propio\"}],\"Productos\":[{\"nombre\":\"Desarrollo Web Full Stack\",\"headline\":\"Aplicaciones web modernas y escalables\",\"descripcion\":\"Desde landing pages hasta aplicaciones empresariales complejas. Desarrollamos con las tecnologías más modernas: React, Vue, Node.js, Python. Diseño responsive, rendimiento optimizado y código mantenible.\",\"servicio_asociado\":\"🔧 Desarrollamos aplicaciones web a medida con tecnologías modernas. UX/UI, desarrollo, testing y deployment incluidos.\",\"imagen\":\"/images/services/productos/desarrollo/4.1.png\",\"caracteristicas\":[\"Diseño responsive\",\"APIs REST/GraphQL\",\"Despliegue en la nube\"]},{\"nombre\":\"Aplicaciones Móviles\",\"headline\":\"Su negocio en el bolsillo de sus clientes\",\"descripcion\":\"Apps nativas e híbridas para iOS y Android. Desde apps de productividad interna hasta aplicaciones de cara al cliente. Offline-first, notificaciones push, integración con hardware del dispositivo.\",\"servicio_asociado\":\"🔧 Desarrollamos apps móviles con Flutter, React Native o desarrollo nativo. Publicación en stores y mantenimiento incluido.\",\"imagen\":\"/images/services/productos/desarrollo/4.2.png\",\"caracteristicas\":[\"iOS y Android\",\"Notificaciones push\",\"Modo offline\"]},{\"nombre\":\"Sistemas ERP/CRM\",\"headline\":\"Gestión integral de su operación\",\"descripcion\":\"Software de gestión empresarial a la medida de su operación. Ventas, compras, inventario, contabilidad, RRHH: todo integrado en una sola plataforma. Reportes en tiempo real para decisiones informadas.\",\"servicio_asociado\":\"🔧 Implementamos y personalizamos ERP/CRM sobre plataformas existentes o desarrollo 100% a medida según complejidad.\",\"imagen\":\"/images/services/productos/desarrollo/4.3.png\",\"caracteristicas\":[\"Módulos integrados\",\"Reportes avanzados\",\"Multi-sucursal\"]},{\"nombre\":\"Automatización de Procesos\",\"headline\":\"Elimine tareas repetitivas, libere talento\",\"descripcion\":\"RPA y workflows para automatizar lo que no agrega valor. Desde ingreso de datos hasta aprobaciones complejas. ROI medible desde el primer mes.\",\"servicio_asociado\":\"🔧 Implementamos automatizaciones con Power Automate, Zapier o desarrollo de bots a medida. Análisis de procesos incluido.\",\"imagen\":\"/images/services/productos/desarrollo/4.4.png\",\"caracteristicas\":[\"ROI medible\",\"Integración multi-sistema\",\"Monitoreo en tiempo real\"]},{\"nombre\":\"Integración de Sistemas\",\"headline\":\"Conectamos sus sistemas para que hablen entre sí\",\"descripcion\":\"¿Datos en silos? Desarrollamos APIs, middleware y conectores para integrar cualquier sistema: ERP, CRM, e-commerce, bancos, proveedores. Sincronización en tiempo real o por lotes.\",\"servicio_asociado\":\"🔧 Desarrollamos integraciones mediante APIs, web services, ETL y conectores nativos. Documentación y soporte incluidos.\",\"imagen\":\"/images/services/productos/desarrollo/4.5.png\",\"caracteristicas\":[\"APIs personalizadas\",\"ETL de datos\",\"Sincronización en tiempo real\"]},{\"nombre\":\"Business Intelligence\",\"headline\":\"Transforme datos en decisiones\",\"descripcion\":\"Dashboards y reportes que muestran lo que realmente importa. KPIs en tiempo real, alertas automáticas, drill-down para análisis profundo. Datos de múltiples fuentes en una sola vista.\",\"servicio_asociado\":\"🔧 Implementamos soluciones BI con Power BI, Tableau o desarrollo propio. Modelado de datos y capacitación incluidos.\",\"imagen\":\"/images/services/productos/desarrollo/4.6.png\",\"caracteristicas\":[\"Dashboards interactivos\",\"KPIs en tiempo real\",\"Alertas automáticas\"]}],\"PorQueElegirnos\":[\"Equipo de desarrollo propio en Argentina\",\"Metodologías ágiles certificadas\",\"Código fuente 100% propiedad del cliente\"],\"ServiciosLista\":[\"Desarrollo web y aplicaciones móviles\",\"Sistemas de gestión ERP/CRM\",\"Automatización de procesos\",\"Integración de APIs y sistemas\"],\"AntecedentesIds\":[2496,3074],\"LocalFallbackImage\":\"/img/sync-offline/be4911d3-7a71-457e-a081-97d0472c4aa9.png\"},{\"id\":105,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-17T17:36:11.089Z\",\"user_updated\":null,\"date_updated\":\"2026-01-17T17:36:11.089Z\",\"Titulo\":\"Soporte Técnico 24/7 | Mesa de Ayuda, Mantenimiento IT\",\"Descripcion\":\"Servicio integral de soporte técnico 24/7 en Mendoza, San Juan, Cuyo y Argentina. Mesa de ayuda, mantenimiento preventivo/correctivo, gestión de incidentes, monitoreo proactivo, backup y recuperación. +51 contratos activos. SLA garantizado (respuesta en <30 min). Técnicos certificados. Disponible todos los días del año.\",\"Area\":\"Soporte\",\"Cliente\":null,\"Unidad_de_negocio\":\"Soporte TIC\",\"Imagen\":\"d3bfa8eb-8ba4-4791-a05c-51eb4d1933c2\",\"Presupuesto\":null,\"Servicios_Detalle\":null,\"Caracteristicas\":null,\"original_id\":null,\"Subtitulo\":\"Servicio Técnico Integral para su Infraestructura IT\",\"Tagline\":\"Su tranquilidad tecnológica, nuestra responsabilidad\",\"Stats\":[{\"valor\":\"500+\",\"label\":\"Clientes activos\"},{\"valor\":\"<15min\",\"label\":\"Tiempo de respuesta\"},{\"valor\":\"24/7\",\"label\":\"Disponibilidad\"}],\"Productos\":[{\"imagen\":\"/images/services/productos/soporte/5.1.png\",\"nombre\":\"Mesa de Ayuda 24/7\",\"headline\":\"Soporte técnico cuando lo necesite\",\"descripcion\":\"Un problema técnico a las 3am puede paralizar su operación. Nuestra mesa de ayuda está disponible las 24 horas, los 7 días. Técnicos certificados, herramientas de diagnóstico remoto, escalamiento definido.\",\"caracteristicas\":[\"Respuesta en 15 minutos\",\"Soporte remoto y presencial\",\"Tickets ilimitados\"],\"servicio_asociado\":\"🔧 Brindamos soporte nivel 1, 2 y 3 con SLA garantizado. Tickets ilimitados, reportes mensuales, mejora continua.\"},{\"imagen\":\"/images/services/productos/soporte/5.2.png\",\"nombre\":\"Mantenimiento Preventivo\",\"headline\":\"Anticipamos los problemas antes de que ocurran\",\"descripcion\":\"El mantenimiento reactivo cuesta más que el preventivo. Visitamos periódicamente, actualizamos, limpiamos, verificamos backups, revisamos logs. Cuando algo está por fallar, lo detectamos a tiempo.\",\"caracteristicas\":[\"Actualizaciones de seguridad\",\"Limpieza de equipos\",\"Reportes mensuales\"],\"servicio_asociado\":\"🔧 Realizamos mantenimiento programado de servidores, switches, firewalls y endpoints. Reportes y recomendaciones incluidos.\"},{\"imagen\":\"/images/services/productos/soporte/5.3.png\",\"nombre\":\"Monitoreo Proactivo 24/7\",\"headline\":\"Vigilamos su infraestructura mientras usted duerme\",\"descripcion\":\"Dashboards en tiempo real, alertas inteligentes, correlación de eventos. Sabemos que un servidor tiene poca memoria antes de que se caiga. Intervenimos proactivamente para evitar incidentes.\",\"caracteristicas\":[\"Detección temprana\",\"Alertas automáticas\",\"Dashboards en tiempo real\"],\"servicio_asociado\":\"🔧 Implementamos monitoreo con Zabbix, Nagios o herramientas enterprise. Alertas, dashboards y respuesta automatizada.\"},{\"imagen\":\"/images/services/productos/soporte/5.4.png\",\"nombre\":\"Gestión de Incidentes ITIL\",\"headline\":\"Procesos certificados para resolver problemas\",\"descripcion\":\"No improvisamos. Seguimos metodología ITIL para gestión de incidentes: registro, clasificación, priorización, escalamiento, resolución, análisis de causa raíz. Mejora continua documentada.\",\"caracteristicas\":[\"Escalamiento definido\",\"SLAs por prioridad\",\"Análisis de causa raíz\"],\"servicio_asociado\":\"🔧 Gestionamos incidentes con herramientas ITSM profesionales. SLAs diferenciados por prioridad, reportes ejecutivos.\"},{\"imagen\":\"/images/services/productos/soporte/5.5.png\",\"nombre\":\"Backup y Recuperación\",\"headline\":\"Sus datos protegidos ante cualquier evento\",\"descripcion\":\"Ransomware, falla de disco, error humano: las amenazas son reales. Implementamos backup automático, verificamos restauración, guardamos copias offsite. Dormirá tranquilo sabiendo que puede recuperarse.\",\"caracteristicas\":[\"Backup automático\",\"Recuperación rápida\",\"Pruebas periódicas\"],\"servicio_asociado\":\"🔧 Implementamos soluciones de backup local, en nube e híbrido. Testing de restauración periódico y DR planning.\"}],\"PorQueElegirnos\":[\"Personal técnico certificado\",\"SLAs garantizados por contrato\",\"Herramientas de gestión ITSM profesionales\"],\"ServiciosLista\":[\"Mesa de ayuda nivel 1, 2 y 3\",\"Mantenimiento preventivo programado\",\"Gestión de incidentes ITIL\",\"Monitoreo proactivo de infraestructura\"],\"AntecedentesIds\":null,\"LocalFallbackImage\":\"/img/sync-offline/d3bfa8eb-8ba4-4791-a05c-51eb4d1933c2.png\"},{\"id\":106,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-17T17:36:11.089Z\",\"user_updated\":null,\"date_updated\":\"2026-01-17T17:36:11.089Z\",\"Titulo\":\"Consultoría IT y Transformación Digital | Arquitectura, Auditoría\",\"Descripcion\":\"Asesoramiento estratégico en tecnología para Mendoza, Cuyo, Patagonia y Argentina. Consultoría IT, arquitectura empresarial, auditorías de seguridad, planificación estratégica, evaluación de proveedores, transformación digital, roadmap tecnológico. +100 proyectos en minería, gobierno, bodegas, constructoras y salud. Metodologías ITIL, COBIT, TOGAF.\",\"Area\":\"Consultoría\",\"Cliente\":null,\"Unidad_de_negocio\":\"Consultoría\",\"Imagen\":\"b104c9b7-708f-4cc7-ab7f-5f8443a2475e\",\"Presupuesto\":null,\"Servicios_Detalle\":null,\"Caracteristicas\":null,\"original_id\":null,\"Subtitulo\":\"Asesoramiento Estratégico en Tecnología\",\"Tagline\":\"Decisiones tecnológicas informadas y respaldadas\",\"Stats\":[{\"valor\":\"100+\",\"label\":\"Proyectos de consultoría\"},{\"valor\":\"25+\",\"label\":\"Años de experiencia\"},{\"valor\":\"360°\",\"label\":\"Visión integral\"}],\"Productos\":[{\"imagen\":\"/images/services/productos/consultoria/6.1.png\",\"nombre\":\"Auditoría de Infraestructura IT\",\"headline\":\"Diagnóstico completo de su estado tecnológico\",\"descripcion\":\"¿Su infraestructura está preparada para lo que viene? Evaluamos redes, servidores, seguridad, procesos y capacidades. Informe ejecutivo con hallazgos, riesgos y roadmap de mejoras priorizado.\",\"caracteristicas\":[\"Informe ejecutivo\",\"Roadmap de mejoras\",\"Priorización por impacto\"],\"servicio_asociado\":\"🔧 Realizamos auditorías técnicas completas con herramientas especializadas. Informe ejecutivo y técnico, presentación a directivos.\"},{\"imagen\":\"/images/services/productos/consultoria/6.2.png\",\"nombre\":\"Planificación Estratégica IT\",\"headline\":\"Tecnología alineada con objetivos de negocio\",\"descripcion\":\"La tecnología debe servir al negocio, no al revés. Desarrollamos planes IT a 3-5 años que acompañan su estrategia de crecimiento. Inversiones justificadas con ROI proyectado.\",\"caracteristicas\":[\"Visión a largo plazo\",\"Presupuesto detallado\",\"Hitos medibles\"],\"servicio_asociado\":\"🔧 Desarrollamos planes estratégicos IT con análisis de brechas, roadmap de inversiones y governance recomendado.\"},{\"imagen\":\"/images/services/productos/consultoria/6.3.png\",\"nombre\":\"Arquitectura Empresarial\",\"headline\":\"Diseño de la estructura tecnológica óptima\",\"descripcion\":\"Aplicaciones, datos, infraestructura: todo conectado de forma coherente. Diseñamos arquitecturas que evitan redundancias, facilitan la integración y permiten la evolución ordenada.\",\"caracteristicas\":[\"Diagramas técnicos\",\"Documentación completa\",\"Gobernanza IT\"],\"servicio_asociado\":\"🔧 Aplicamos frameworks TOGAF y Zachman para diseñar su arquitectura enterprise. Documentación y governance incluidos.\"},{\"imagen\":\"/images/services/productos/consultoria/6.4.png\",\"nombre\":\"Evaluación de Riesgos IT\",\"headline\":\"Identifique vulnerabilidades antes de que sea tarde\",\"descripcion\":\"Ciberseguridad, disponibilidad, cumplimiento: los riesgos IT son reales. Identificamos, cuantificamos y priorizamos. Plan de mitigación concreto y monitoreo continuo de exposición.\",\"caracteristicas\":[\"Matriz de riesgos\",\"Plan de mitigación\",\"Monitoreo continuo\"],\"servicio_asociado\":\"🔧 Realizamos análisis de riesgos con metodología ISO 27005. Matriz de riesgos, planes de mitigación y seguimiento.\"},{\"imagen\":\"/images/services/productos/consultoria/6.5.png\",\"nombre\":\"Cumplimiento Normativo\",\"headline\":\"Asegure el cumplimiento de regulaciones\",\"descripcion\":\"ISO 27001, PCI-DSS, Ley de Datos Personales, regulaciones sectoriales. Evaluamos su estado actual, identificamos brechas y acompañamos la remediación. Preparación para auditorías externas.\",\"caracteristicas\":[\"Gap analysis\",\"Plan de remediación\",\"Preparación para auditorías\"],\"servicio_asociado\":\"🔧 Asesoramos en cumplimiento de ISO 27001, PCI-DSS, GDPR y normativas locales. Gap analysis y plan de remediación.\"}],\"PorQueElegirnos\":[\"Consultores senior con experiencia regional\",\"Metodologías probadas internacionalmente\",\"Enfoque práctico orientado a resultados\"],\"ServiciosLista\":[\"Auditorías de infraestructura IT\",\"Planificación estratégica tecnológica\",\"Arquitectura empresarial\",\"Evaluación de riesgos y cumplimiento\"],\"AntecedentesIds\":null,\"LocalFallbackImage\":\"/img/sync-offline/b104c9b7-708f-4cc7-ab7f-5f8443a2475e.png\"},{\"id\":107,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-18T13:59:55.817Z\",\"user_updated\":null,\"date_updated\":\"2026-01-18T13:59:55.817Z\",\"Titulo\":\"Sistemas de Detección y Alarma de Incendios\",\"Descripcion\":\"Protección integral contra el fuego desde el primer segundo. Diseñamos, instalamos y mantenemos sistemas de detección temprana que salvan vidas y protegen activos críticos. Tecnología direccionable e inteligente.\",\"Area\":\"Seguridad\",\"Cliente\":null,\"Unidad_de_negocio\":null,\"Imagen\":\"7707d106-f6a9-4fcf-83fc-2cdcc417c4ad\",\"Presupuesto\":null,\"Servicios_Detalle\":[{\"nombre\":\"Panel Central de Alarma Direccionable\",\"headline\":\"El cerebro que identifica dónde está el fuego en segundos\",\"descripcion\":\"En un edificio con 500 detectores, saber que 'hay alarma' no alcanza. Necesita saber exactamente en qué habitación. Nuestros paneles direccionables identifican el dispositivo exacto que detectó el problema, acelerando la respuesta y evacuación.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos sistemas SDI direccionables con paneles Notifier, Hochiki o equivalente. Programación por zonas, integración con BMS y habilitación ante Bomberos incluida.\",\"caracteristicas\":[\"Localización exacta del incendio\",\"Reducción de falsas alarmas\",\"Cumplimiento NFPA 72\"],\"imagen\":\"/directus-assets/91d4f254-cef6-4b50-8159-8e3aeb944d5b\"},{\"nombre\":\"Detectores Fotoeléctricos de Humo\",\"headline\":\"Segundos de ventaja que salvan vidas\",\"descripcion\":\"El humo viaja más rápido que las llamas. Nuestros detectores fotoeléctricos identifican partículas de combustión antes de que el fuego sea visible. Cada segundo de anticipación es tiempo para evacuar y actuar. Diseñados para minimizar falsas alarmas.\",\"servicio_asociado\":\"🔧 Instalamos detectores de humo fotoeléctricos convencionales y direccionables. Cálculo de cobertura según NFPA 72, altura de techo y tipo de ambiente.\",\"caracteristicas\":[\"Detección en fase temprana\",\"Mínimas falsas alarmas\",\"Cobertura calculada\"],\"imagen\":\"/directus-assets/cd8d23b1-68b9-4ada-9c69-3fd3f94c0699\"},{\"nombre\":\"Detectores Térmicos para Ambientes Especiales\",\"headline\":\"Protección donde el humo no es confiable\",\"descripcion\":\"Cocinas, calderas, estacionamientos. Lugares donde el humo es normal pero el fuego no. Los detectores térmicos activan la alarma por temperatura, no por partículas. Protección inteligente adaptada a cada ambiente.\",\"servicio_asociado\":\"🔧 Instalamos detectores térmicos de temperatura fija y termovelocimétricos para ambientes donde los detectores de humo no son prácticos. Selección según clase de temperatura requerida.\",\"caracteristicas\":[\"Cero falsas alarmas por vapor o humo normal\",\"Ideal para cocinas y calderas\",\"Clasificación por temperatura\"],\"imagen\":\"/directus-assets/807c7e23-376f-426d-80c8-0047fef223dc\"},{\"nombre\":\"Detectores de Llama para Alta Velocidad\",\"headline\":\"Detección instantánea donde cada milisegundo cuenta\",\"descripcion\":\"En ambientes con combustibles, explosivos o procesos críticos, esperar a que se forme humo no es opción. Los detectores UV/IR identifican la radiación de la llama en milisegundos, activando supresión automática antes de que el fuego se propague.\",\"servicio_asociado\":\"🔧 Instalamos detectores de llama UV/IR para plantas industriales, hangares, depósitos de combustibles y áreas de alto riesgo. Integración con sistemas de supresión automática.\",\"caracteristicas\":[\"Respuesta en milisegundos\",\"Visión de largo alcance\",\"Integración con supresión\"],\"imagen\":\"/directus-assets/a5efe4ce-52ad-49ae-b892-da064d3d294a\"},{\"nombre\":\"Notificación Audible y Visual de Alarma\",\"headline\":\"Que nadie se quede sin enterarse\",\"descripcion\":\"La alarma suena, pero ¿todos la escuchan? En ambientes ruidosos o con personas con discapacidad auditiva, las sirenas estroboscópicas garantizan que TODOS perciban la emergencia. Luz y sonido combinados para evacuación efectiva.\",\"servicio_asociado\":\"🔧 Instalamos dispositivos de notificación audibles y visuales cumpliendo requisitos ADA de accesibilidad. Cálculo de intensidad lumínica y nivel sonoro según normativa.\",\"caracteristicas\":[\"Cumplimiento de accesibilidad\",\"Penetra el ruido ambiental\",\"Sincronización de destellos\"],\"imagen\":\"/directus-assets/21d34461-dfeb-46dc-91c9-eebea58acc87\"},{\"nombre\":\"Estaciones Manuales de Activación\",\"headline\":\"Cualquier persona puede dar la voz de alarma\",\"descripcion\":\"Cuando alguien ve fuego antes que el sistema, necesita poder alertar a todos. Las estaciones manuales estratégicamente ubicadas permiten activar la alarma general con un simple tirón. Visibilidad máxima en color rojo normativo.\",\"servicio_asociado\":\"🔧 Instalamos estaciones manuales en ubicaciones normativas: salidas de emergencia, escaleras y pasillos a distancias máximas establecidas por NFPA 72.\",\"caracteristicas\":[\"Activación instantánea\",\"Ubicación normativa\",\"Alta visibilidad\"],\"imagen\":\"/directus-assets/f92a046d-079e-41c7-b124-ccf953029083\"},{\"nombre\":\"Módulos de Integración y Control\",\"headline\":\"Conectamos la detección con la acción\",\"descripcion\":\"Detectar no alcanza, hay que actuar. Nuestros módulos conectan el sistema de alarma con puertas cortafuego, ascensores, HVAC y sistemas de supresión. Cuando hay alarma, todo el edificio responde coordinadamente.\",\"servicio_asociado\":\"🔧 Instalamos módulos de control y monitoreo para integrar el SDI con otros sistemas del edificio: liberación de puertas, retorno de ascensores, apagado de HVAC y activación de supresión.\",\"caracteristicas\":[\"Respuesta coordinada\",\"Puertas que liberan solas\",\"Ascensores a planta baja\"],\"imagen\":\"/directus-assets/0948d501-3a88-462c-b1d3-15bd335d0e9b\"},{\"nombre\":\"Integración con Sistemas de Extinción\",\"headline\":\"De la detección a la supresión automática\",\"descripcion\":\"En salas de servidores, archivos y áreas críticas, detectar no basta: hay que extinguir antes de que haya daño. Integramos la detección con sistemas de supresión por agentes limpios, CO2 o agua nebulizada para respuesta automática.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos integración SDI-supresión con sistemas de agentes limpios (FM-200, Novec), CO2 y agua nebulizada. Pre-alarma, alarma, retardo y disparo automático.\",\"caracteristicas\":[\"Supresión automática\",\"Agentes limpios\",\"Secuencia de pre-alarma\"],\"imagen\":\"/directus-assets/2107d4e1-9e13-43b1-aca4-c146d42d1426\"}],\"Caracteristicas\":[\"Certificación NFPA 72\",\"Habilitación de Bomberos\",\"Sistemas Direccionables Inteligentes\"],\"original_id\":null,\"Subtitulo\":\"Ingeniería SDI con Certificación NFPA 72 y Habilitación de Bomberos\",\"Tagline\":\"Protección integral contra el fuego desde el primer segundo\",\"Stats\":null,\"Productos\":null,\"PorQueElegirnos\":null,\"ServiciosLista\":null,\"AntecedentesIds\":null,\"LocalFallbackImage\":\"/img/sync-offline/7707d106-f6a9-4fcf-83fc-2cdcc417c4ad.png\"},{\"id\":108,\"status\":\"published\",\"user_created\":null,\"date_created\":\"2026-01-18T13:59:56.543Z\",\"user_updated\":null,\"date_updated\":\"2026-01-18T13:59:56.543Z\",\"Titulo\":\"Servicios Eléctricos para IT\",\"Descripcion\":\"Energía confiable para infraestructura crítica. Diseñamos e instalamos sistemas eléctricos dedicados, UPS online, bancos de baterías y puesta a tierra técnica para asegurar que sus datos nunca se detengan por falta de energía.\",\"Area\":\"Infraestructura\",\"Cliente\":null,\"Unidad_de_negocio\":null,\"Imagen\":\"050fc7d2-67cb-4943-af0a-afba1230e9bd\",\"Presupuesto\":null,\"Servicios_Detalle\":[{\"nombre\":\"Tableros Eléctricos para Circuitos IT\",\"headline\":\"Energía dedicada y protegida para su infraestructura crítica\",\"descripcion\":\"Sus equipos IT no pueden compartir circuito con el aire acondicionado o la cafetera. Diseñamos e instalamos tableros eléctricos dedicados para informática: circuitos separados, protecciones adecuadas, puesta a tierra técnica y medición independiente.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos tableros eléctricos dedicados para salas de servidores y data centers. Protecciones termomagnéticas, diferenciales, supresores de transitorios y barra de tierra aislada.\",\"caracteristicas\":[\"Aislamiento de ruido eléctrico\",\"Protección contra sobretensiones\",\"Puesta a tierra técnica\"],\"imagen\":\"/directus-assets/7f189c6d-dd52-4ef9-8114-a00afa26b73b\"},{\"nombre\":\"Sistemas de Alimentación Ininterrumpida (UPS)\",\"headline\":\"Cero interrupciones, cero pérdida de datos\",\"descripcion\":\"Un corte de luz de un segundo puede significar horas de recuperación. Los UPS Online de doble conversión mantienen sus equipos funcionando sin parpadeos: durante cortes, durante tormentas, durante todo. Autonomía desde minutos hasta horas según su necesidad.\",\"servicio_asociado\":\"🔧 Instalamos sistemas UPS desde 1 kVA para racks individuales hasta 500 kVA para data centers completos. Online doble conversión, bypass automático y monitoreo remoto incluido.\",\"caracteristicas\":[\"Transición imperceptible\",\"Regulación constante\",\"Monitoreo remoto\"],\"imagen\":\"/directus-assets/65df1f7d-337d-4dbc-aa1d-27296c493749\"},{\"nombre\":\"Bancos de Baterías para Autonomía Extendida\",\"headline\":\"Horas de respaldo cuando los minutos no alcanzan\",\"descripcion\":\"¿Cuánto tiempo necesita funcionar sin red eléctrica? ¿15 minutos para apagar ordenadamente? ¿2 horas hasta que llegue el generador? ¿8 horas de autonomía total? Dimensionamos bancos de baterías para su tiempo de respaldo requerido.\",\"servicio_asociado\":\"🔧 Dimensionamos e instalamos bancos de baterías de plomo-ácido o litio para autonomías extendidas. Rack de baterías, cableado, protecciones y mantenimiento preventivo incluido.\",\"caracteristicas\":[\"Autonomía a medida\",\"Baterías de grado UPS\",\"Mantenimiento preventivo\"],\"imagen\":\"/directus-assets/00a2a6e9-56cd-4b9f-8393-48d0f038c96b\"},{\"nombre\":\"Tableros de Transferencia Automática\",\"headline\":\"Del UPS al generador sin intervención humana\",\"descripcion\":\"Cuando el corte se extiende y el UPS se agota, el generador debe tomar la carga. Los tableros de transferencia automática (ATS) hacen el cambio sin operador: detectan la falla, arrancan el generador, transfieren la carga y vuelven a red cuando se normaliza.\",\"servicio_asociado\":\"🔧 Instalamos tableros de transferencia automática (ATS) para conmutación entre red comercial, UPS y generador. Secuencia de arranque, sincronización y retransferencia programable.\",\"caracteristicas\":[\"Transferencia sin operador\",\"Secuencia programable\",\"Monitoreo de fuentes\"],\"imagen\":\"/directus-assets/ef00b9aa-c2f4-466f-a72a-7c6da50d9353\"},{\"nombre\":\"Unidades de Distribución de Energía en Rack (PDU)\",\"headline\":\"Energía organizada dentro de cada rack\",\"descripcion\":\"Del tablero al UPS, del UPS a... ¿dónde? Las PDU distribuyen la energía dentro de cada rack de forma organizada: múltiples tomas, protección individual por circuito, medición de consumo y en algunos casos, control remoto de cada toma.\",\"servicio_asociado\":\"🔧 Instalamos PDUs básicas, monitoreadas e inteligentes. Montaje vertical u horizontal, con o sin medición, con o sin switching remoto según necesidad.\",\"caracteristicas\":[\"Distribución organizada\",\"Medición de consumo\",\"Control remoto\"],\"imagen\":\"/directus-assets/242d8b05-05c9-469a-b073-f614ed9eaa87\"},{\"nombre\":\"Puesta a Tierra Técnica\",\"headline\":\"La referencia de tierra que sus equipos necesitan\",\"descripcion\":\"Los equipos electrónicos sensibles no toleran ruido en la tierra. Una puesta a tierra técnica (TGB/SRS) proporciona una referencia limpia, separada del sistema de tierras de fuerza. Medimos, diseñamos e instalamos según norma TIA-607.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos sistemas de puesta a tierra técnica según TIA-607: barra principal (TMGB), barras secundarias (TGB), malla equipotencial y medición de resistividad.\",\"caracteristicas\":[\"Referencia limpia\",\"Cumplimiento TIA-607\",\"Medición certificada\"],\"imagen\":\"/directus-assets/9deca29b-8589-40d2-b1c5-4add30813f77\"},{\"nombre\":\"Banco de Capacitores\",\"headline\":\"Pague solo por la energía que realmente usa\",\"descripcion\":\"¿Su factura eléctrica tiene recargo por bajo factor de potencia? Los bancos de capacitores corrigen el desfase entre tensión y corriente, mejorando la eficiencia de su instalación y eliminando penalizaciones. El ahorro paga la inversión.\",\"servicio_asociado\":\"🔧 Instalamos bancos de capacitores automáticos para corrección de factor de potencia. Medición previa, dimensionamiento, instalación y verificación de factura posterior.\",\"caracteristicas\":[\"Elimina recargos\",\"ROI en meses\",\"Mayor capacidad disponible\"],\"imagen\":\"/directus-assets/e1249bd3-ed11-4fe0-a2f2-2116eba663f7\"},{\"nombre\":\"Instalaciones Eléctricas para Data Centers\",\"headline\":\"Ingeniería eléctrica de punta a punta para infraestructura crítica\",\"descripcion\":\"Desde la acometida hasta el último rack: diseñamos e instalamos la infraestructura eléctrica completa para data centers. Redundancia N+1 o 2N, selectividad de protecciones, tierras técnicas y cumplimiento de TIA-942. Su data center, listo para certificar.\",\"servicio_asociado\":\"🔧 Diseñamos e instalamos infraestructura eléctrica completa para data centers: acometida, transformadores, tableros generales y de distribución, canalizaciones, UPS, baterías, transferencia y PDUs.\",\"caracteristicas\":[\"Diseño integral\",\"Redundancia según tier\",\"Cumplimiento TIA-942\"],\"imagen\":\"/directus-assets/e12371d4-97bf-4f62-86a3-4cba429863a6\"}],\"Caracteristicas\":[\"Redundancia N+1 / 2N\",\"Cumplimiento TIA-942\",\"Cero interrupciones\"],\"original_id\":null,\"Subtitulo\":\"Instalaciones Eléctricas, UPS y Energía Ininterrumpida para Data Centers\",\"Tagline\":\"Energía confiable para infraestructura crítica\",\"Stats\":null,\"Productos\":null,\"PorQueElegirnos\":null,\"ServiciosLista\":null,\"AntecedentesIds\":[3119,3381,3581],\"LocalFallbackImage\":\"/img/sync-offline/050fc7d2-67cb-4943-af0a-afba1230e9bd.png\"}]");
